import 'dart:async';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:flutter_foreground_task/flutter_foreground_task.dart';
import 'package:geolocator/geolocator.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'location_service.dart';

class ConnectedScreen extends StatefulWidget {
  const ConnectedScreen({super.key, required this.data});
    final Map<String, dynamic> data;

      @override
        State<ConnectedScreen> createState() => _ConnectedScreenState();
        }

        class _ConnectedScreenState extends State<ConnectedScreen> {
          static const _prefKey = 'sharing_for_code';
            final String _uid = FirebaseAuth.instance.currentUser!.uid;
              bool _sharing = false;
                String? _message;
                  String? _serviceError;
                    DateTime? _lastSent;

                      String get _code => (widget.data['code'] ?? '').toString();

                        DocumentReference<Map<String, dynamic>> get _locRef =>
                              FirebaseFirestore.instance.collection('locations').doc(_uid);

                                @override
                                  void initState() {
                                      super.initState();
                                          FlutterForegroundTask.addTaskDataCallback(_onTaskData);
                                              _initService();
                                                  _restore();
                                                    }

                                                      @override
                                                        void dispose() {
                                                            FlutterForegroundTask.removeTaskDataCallback(_onTaskData);
                                                                super.dispose();
                                                                  }

                                                                    void _initService() {
                                                                        FlutterForegroundTask.init(
                                                                              androidNotificationOptions: AndroidNotificationOptions(
                                                                                      channelId: 'location_sharing',
                                                                                              channelName: 'Location sharing',
                                                                                                      channelDescription:
                                                                                                                  'Location sharing চালু থাকলে এই notification দেখা যায়।',
                                                                                                                          onlyAlertOnce: true,
                                                                                                                                ),
                                                                                                                                      iosNotificationOptions:
                                                                                                                                                const IOSNotificationOptions(showNotification: false, playSound: false),
                                                                                                                                                      foregroundTaskOptions: ForegroundTaskOptions(
                                                                                                                                                              eventAction: ForegroundTaskEventAction.repeat(60000),
                                                                                                                                                                      autoRunOnBoot: true,
                                                                                                                                                                              autoRunOnMyPackageReplaced: true,
                                                                                                                                                                                      allowWakeLock: true,
                                                                                                                                                                                              allowWifiLock: true,
                                                                                                                                                                                                    ),
                                                                                                                                                                                                        );
                                                                                                                                                                                                          }

                                                                                                                                                                                                            void _onTaskData(Object data) {
                                                                                                                                                                                                                if (data is! Map || !mounted) return;
                                                                                                                                                                                                                    if (data['type'] == 'sent') {
                                                                                                                                                                                                                          final ms = data['ms'];
                                                                                                                                                                                                                                if (ms is int) {
                                                                                                                                                                                                                                        setState(() {
                                                                                                                                                                                                                                                  _lastSent = DateTime.fromMillisecondsSinceEpoch(ms);
                                                                                                                                                                                                                                                            _serviceError = null;
                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                              } else if (data['type'] == 'error') {
                                                                                                                                                                                                                                                                                    setState(() => _serviceError = data['msg']?.toString());
                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                            // আগে ON থাকলে: service চলছে ধরে নেওয়া, না চললে নিজে থেকে চালু
                                                                                                                                                                                                                                                                                              Future<void> _restore() async {
                                                                                                                                                                                                                                                                                                  final prefs = await SharedPreferences.getInstance();
                                                                                                                                                                                                                                                                                                      if (prefs.getString(_prefKey) != _code) return;
                                                                                                                                                                                                                                                                                                          if (await FlutterForegroundTask.isRunningService) {
                                                                                                                                                                                                                                                                                                                if (mounted) setState(() => _sharing = true);
                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                          await _start(auto: true);
                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                  Future<bool> _ensurePermissions({required bool ask}) async {
                                                                                                                                                                                                                                                                                                                                      if (!await Geolocator.isLocationServiceEnabled()) {
                                                                                                                                                                                                                                                                                                                                            _message = 'Phone-এর Location (GPS) চালু করুন';
                                                                                                                                                                                                                                                                                                                                                  return false;
                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                          var perm = await Geolocator.checkPermission();
                                                                                                                                                                                                                                                                                                                                                              if (perm == LocationPermission.denied && ask) {
                                                                                                                                                                                                                                                                                                                                                                    perm = await Geolocator.requestPermission();
                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                            if (perm == LocationPermission.denied ||
                                                                                                                                                                                                                                                                                                                                                                                    perm == LocationPermission.deniedForever) {
                                                                                                                                                                                                                                                                                                                                                                                          _message =
                                                                                                                                                                                                                                                                                                                                                                                                    'Location permission দেওয়া হয়নি। Settings → Apps → Child App → Permissions → Location → "While using the app" দিন';
                                                                                                                                                                                                                                                                                                                                                                                                          return false;
                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                  var notif = await FlutterForegroundTask.checkNotificationPermission();
                                                                                                                                                                                                                                                                                                                                                                                                                      if (notif != NotificationPermission.granted && ask) {
                                                                                                                                                                                                                                                                                                                                                                                                                            await FlutterForegroundTask.requestNotificationPermission();
                                                                                                                                                                                                                                                                                                                                                                                                                                  notif = await FlutterForegroundTask.checkNotificationPermission();
                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                          if (notif != NotificationPermission.granted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                _message =
                                                                                                                                                                                                                                                                                                                                                                                                                                                          'Notification permission ছাড়া sharing চালু হবে না, কারণ চলার সময় notification-এ দেখানো বাধ্যতামূলক';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (ask && !await FlutterForegroundTask.isIgnoringBatteryOptimizations) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await FlutterForegroundTask.requestIgnoreBatteryOptimization();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Future<void> _start({bool auto = false}) async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              _message = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  final ok = await _ensurePermissions(ask: !auto);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (auto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await _stop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (mounted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setState(() {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await FlutterForegroundTask.saveData(key: 'uid', value: _uid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (await FlutterForegroundTask.isRunningService) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await FlutterForegroundTask.restartService();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          await FlutterForegroundTask.startService(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  serviceId: 301,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          notificationTitle: 'Location sharing চালু আছে',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  notificationText:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'Parent আপনার location দেখতে পাচ্ছেন। বন্ধ করতে app খুলুন।',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      callback: startLocationService,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final running = await FlutterForegroundTask.isRunningService;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (running) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final prefs = await SharedPreferences.getInstance();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await prefs.setString(_prefKey, _code);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              _message = 'Sharing চালু করা যায়নি, আবার চেষ্টা করুন';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (mounted) setState(() => _sharing = running);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Future<void> _stop() async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await FlutterForegroundTask.stopService();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  final prefs = await SharedPreferences.getInstance();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await prefs.remove(_prefKey);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          _locRef.set({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'sharing': false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'stoppedAt': FieldValue.serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }).catchError((_) {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (mounted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setState(() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            _sharing = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _lastSent = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Future<void> _onToggle(bool on) async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!on) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await _stop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final agreed = await showDialog<bool>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                context: context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      builder: (ctx) => AlertDialog(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              title: const Text('Location শেয়ার করবেন?'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      content: const Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'চালু করলে Parent আপনার phone-এর অবস্থান দেখতে পারবেন। App swipe করে বন্ধ করলেও এটা চলতে থাকবে এবং notification-এ সবসময় দেখা যাবে। বন্ধ করতে এই app খুলে সুইচ OFF করুন।'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          actions: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    TextButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onPressed: () => Navigator.pop(ctx, false),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: const Text('না')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          FilledButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onPressed: () => Navigator.pop(ctx, true),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      child: const Text('রাজি আছি')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (agreed == true) await _start();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Future<void> _disconnect() async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await FlutterForegroundTask.stopService();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final prefs = await SharedPreferences.getInstance();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await prefs.remove(_prefKey);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                _locRef.delete().catchError((_) {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FirebaseFirestore.instance
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .collection('children')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .doc(_uid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .delete()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .catchError((_) {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final name = widget.data['childName'] ?? '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  final sentText = _lastSent == null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? 'GPS signal-এর অপেক্ষা করা হচ্ছে… (খোলা জায়গায় দ্রুত হয়)'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : 'শেষ পাঠানো: ${TimeOfDay.fromDateTime(_lastSent!).format(context)}';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            appBar: AppBar(title: const Text('Child App')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  body: ListView(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const Icon(Icons.link, size: 64, color: Colors.green),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Center(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Text('Parent-এর সাথে যুক্ত ✅',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: Theme.of(context).textTheme.titleLarge)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Center(child: Text('নাম: $name')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Card(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: SwitchListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        title: const Text('Location শেয়ার করুন'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      subtitle: Text(_sharing
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? '🟢 ON: Parent আপনার location দেখতে পাচ্ছেন\n$sentText'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : '🔴 OFF: কেউ আপনার location দেখতে পাচ্ছে না'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        isThreeLine: _sharing,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value: _sharing,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChanged: _onToggle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (_message != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.only(top: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: Text(_message!, style: const TextStyle(color: Colors.red)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (_serviceError != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: const EdgeInsets.only(top: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Text('⚠️ $_serviceError',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: const TextStyle(color: Colors.red)),
